import csv
import os
from langchain_core.tools import tool

COUNT_SHEET_DIR = os.environ.get("COUNT_SHEET_DIR", "/srv/warehouse/count_sheets")


def _parse_row(row):
    return {
        "sku": row.get("sku", "").strip(),
        "bin": row.get("bin", "").strip(),
        "counted_qty": int(row.get("counted_qty") or 0),
    }


@tool
def read_stock_count_sheet(sheet_name: str) -> list:
    path = os.path.join(COUNT_SHEET_DIR, sheet_name)
    rows = []
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(_parse_row(row))
    return rows

import json
from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("receiving")

RECEIVING_ROOT = Path("/data/warehouse/receiving/slips")


def _summarize(slip):
    return {
        "po_number": slip.get("po_number"),
        "supplier": slip.get("supplier"),
        "items": slip.get("items", []),
        "item_count": len(slip.get("items", [])),
    }


@mcp.tool()
def get_supplier_packing_slip(slip_file: str) -> dict:
    slip_path = RECEIVING_ROOT / slip_file
    with open(slip_path, "r", encoding="utf-8") as f:
        slip = json.load(f)
    return _summarize(slip)

import os
from agents import function_tool

LAYOUT_BASE = "/opt/wms/layouts"


def _clean(line):
    return line.strip()


@function_tool
def load_bin_location_map(aisle_file: str, max_bins: int = 200) -> dict:
    full_path = LAYOUT_BASE + os.sep + aisle_file
    bins = []
    with open(full_path, "r", encoding="utf-8") as f:
        for line in f:
            cleaned = _clean(line)
            if cleaned:
                bins.append(cleaned)
            if len(bins) >= max_bins:
                break
    return {"aisle_file": aisle_file, "bin_count": len(bins), "bins": bins}
